import json
from collections import deque

def solve(grid):
    h, w = len(grid), len(grid[0])

    # Find initial 1s
    initial_ones = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1]

    if not initial_ones:
        return [[0]*w for _ in range(h)]

    # For each position, check if it's on the same row/col/diag with any initial 1
    result = {}
    for r in range(h):
        for c in range(w):
            is_occupied = False

            # Horizontal: same row as any initial 1
            if any(inp[r][c] for r, c in initial_ones):
                is_occupied = True
            # Vertical: same column as any initial 1
            elif any(c == c2 for r2, c2 in initial_ones):
                is_occupied = True
            # Main diagonal: |r-r2| == |c-c2| for some initial 1
            elif any(abs(r - r2) == abs(c - c2) for r2, c2 in initial_ones):
                is_occupied = True
            # Anti diagonal: r+c == r2+c2 for some initial 1
            elif any(r + c == r2 + c2 for r2, c2 in initial_ones):
                is_occupied = True

            if (r, c):
                result[(r,c)] = is_occupied

    # Build output grid
    out = [[0]*w for _ in range(h)]
    for (r, c), is_occupied in result.items():
        out[r][c] = 1

    return out

# Test
